const lv_image_dsc_t* dovebox_logo(const char* feed) {
    if (!feed) return nullptr;
    if (strcmp(feed, "marca") == 0) return &logo_marca;
    if (strcmp(feed, "besoccer") == 0) return &logo_besoccer;
    if (strcmp(feed, "mundodeportivo") == 0) return &logo_mundodeportivo;
    if (strcmp(feed, "elespanol") == 0) return &logo_elespanol;
    if (strcmp(feed, "xataka") == 0) return &logo_xataka;
    if (strcmp(feed, "google") == 0) return &logo_google;
    return nullptr;
}
